'use strict';

function encodeFacetPath(facets) {
  if (!Array.isArray(facets)) {
    throw new TypeError('facets must be an array');
  }

  return facets.map((facet) => {
    if (
      facet === null ||
      typeof facet !== 'object' ||
      typeof facet.name !== 'string' ||
      facet.name.length === 0 ||
      !Array.isArray(facet.values) ||
      !facet.values.every((value) => typeof value === 'string')
    ) {
      throw new TypeError('invalid facet');
    }

    const name = encodeURI(facet.name);
    const values = facet.values.map(encodeURI).join(',');
    return `${name}=${values}`;
  }).join('&');
}

module.exports = { encodeFacetPath };

