'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['encodeFacetPath']);
assert.strictEqual(typeof api.encodeFacetPath, 'function');
const { encodeFacetPath } = api;

assert.strictEqual(encodeFacetPath([]), '');
assert.strictEqual(
  encodeFacetPath([
    { name: 'color', values: ['red', 'blue green'] },
    { name: 'empty facet', values: [] },
    { name: 'x&y', values: ['a,b', '100%', ''] },
    { name: 'color', values: ['red'] }
  ]),
  'color=red,blue%20green&empty%20facet=&x%26y=a%2Cb,100%25,&color=red'
);

const facets = [
  { name: 'kind', values: ['a', 'a', 'b'] },
  { name: 'symbols', values: ['/?#'] }
];
const snapshot = JSON.parse(JSON.stringify(facets));
assert.strictEqual(encodeFacetPath(facets), 'kind=a,a,b&symbols=%2F%3F%23');
assert.deepStrictEqual(facets, snapshot);

for (const invalid of [
  null,
  {},
  'facets',
  [null],
  [{}],
  [{ name: '', values: [] }],
  [{ name: 4, values: [] }],
  [{ name: 'x', values: 'a' }],
  [{ name: 'x', values: [1] }],
  [{ name: 'ok', values: [] }, { name: 'bad', values: [null] }]
]) {
  assert.throws(() => encodeFacetPath(invalid), TypeError);
}

